<script setup lang="ts">
import FeatureTextField from '../components/FeatureTextField.vue'
import {nextReminderAt} from './schedule'
import type {useNotificationPage} from './useNotificationPage'
defineProps<{state:ReturnType<typeof useNotificationPage>}>()
const weekdays=['日','一','二','三','四','五','六']
</script>
