  <template v-if="state.kind==='messages'"><div class="feature-actions"><button role="button" class="feature-button secondary" @click="state.handleUnread">{{ state.unread?'显示全部消息':'只看未读消息' }}</button><button role="button" class="feature-button secondary" :disabled="state.busy" @click="state.handleReadAll">全部标为已读</button></div><button v-for="item in state.messages" :key="item.id" role="button" class="feature-row" @click="state.handleOpen(`/pages/message-detail/index?id=${encodeURIComponent(item.id)}`)"><span class="feature-row-copy"><strong>{{ item.title }}{{ item.readAt?'':' · 未读' }}</strong><p class="feature-muted">{{ new Date(item.at).toLocaleString() }}</p><p class="feature-muted">{{ item.body }}</p></span><span>→</span></button><p v-if="!state.messages.length" class="feature-note">暂无{{ state.unread?'未读':'' }}消息。这里只记录真实学习进展和本机到期提醒。</p><button v-if="state.messages.length>=state.limit" role="button" class="feature-link" @click="state.handleMore">加载更多消息</button><button role="button" class="feature-link" @click="state.handleOpen('/pages/reminders/index')">管理学习提醒 →</button></template>
  <template v-else-if="state.kind==='detail'&&state.message"><div class="feature-hero"><p class="feature-muted">本机消息 · 已读</p><h2>{{ state.message.title }}</h2><p class="feature-muted">{{ new Date(state.message.at).toLocaleString() }}</p></div><p class="message-body">{{ state.message.body }}</p><button role="button" class="feature-button" @click="state.handleOpen(state.messageUrl)">查看相关学习记录</button><button role="button" class="feature-link" @click="state.handleDeleteMessage">删除这条消息</button></template>
  <template v-else-if="state.kind==='reminders'"><div class="feature-hero"><h2>按自己的节奏学习</h2><p class="feature-note">{{ state.capability.description }}</p></div><button role="button" class="feature-link" @click="state.handleOpen('/pages/reminder-capabilities/index')">查看系统提醒与日历能力 →</button><section v-for="item in state.reminders" :key="item.id" class="reminder-card"><div class="feature-row"><span class="feature-row-copy"><strong>{{ item.title }} · {{ item.time }}</strong><p class="feature-muted">{{ item.weekdays.map(day=>'周'+weekdays[day]).join('、') }}</p><p class="feature-muted">{{ item.enabled?'下一次：'+(nextReminderAt(item,new Date())?.toLocaleString()??'无'):'已关闭，不再触发' }}</p></span><button role="switch" :aria-checked="item.enabled" class="feature-link" :disabled="state.busy" @click="state.handleToggle(item)">{{ item.enabled?'关闭提醒':'开启提醒' }}</button></div><div class="feature-actions"><button role="button" class="feature-link" @click="state.handleOpen(`/pages/reminder-edit/index?id=${encodeURIComponent(item.id)}`)">编辑提醒</button><button role="button" class="feature-link" :disabled="!item.enabled||state.busy" @click="state.handleExport(item)">导出未来四周日历</button><button role="button" class="feature-link" @click="state.handleDelete(item)">删除提醒</button></div></section><p v-if="!state.reminders.length" class="feature-note">还没有学习提醒，可以设置星期、时间、勿扰时段与完成免打扰。</p><button role="button" class="feature-button" @click="state.handleOpen('/pages/reminder-edit/index')">新建学习提醒</button><p v-if="state.status" role="status" class="feature-note">{{ state.status }}</p></template>
