<style scoped>.weekday-grid { display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px; }.weekday-grid .feature-button { min-height:44px;padding:8px 2px;font-size:12px; }.message-body { font-size:16px;line-height:2;white-space:pre-wrap;overflow-wrap:anywhere; }.reminder-card { padding-bottom:18px;border-bottom:1px solid var(--color-border); }</style>
